alter table public.order_installments add column if not exists payment_sequence integer; alter table public.order_installments add column if not exists paid_at timestamptz; create index if not exists order_installments_order_status_idx on public.order_installments(order_id,status,due_date);
create or replace function public.get_order_installment_balance(_order_id uuid) returns table(order_id uuid,total_amount numeric,total_paid numeric,balance numeric,next_due_date date,next_installment_id uuid) language sql security definer set search_path=public as $$ select o.id,o.total_amount,coalesce(sum(i.amount_paid),0),greatest(o.total_amount-coalesce(sum(i.amount_paid),0),0),min(i.due_date) filter(where i.status<>'paid'),(array_agg(i.id order by i.due_date) filter(where i.status<>'paid'))[1] from public.orders o left join public.order_installments i on i.order_id=o.id where o.id=_order_id and o.user_id=auth.uid() group by o.id,o.total_amount $$;
create or replace function public.apply_flexible_installment_payment(_order_id uuid,_amount numeric,_payment_id uuid default null) returns numeric language plpgsql security definer set search_path=public as $$ declare remaining numeric:=_amount; r record; applied numeric; begin if _amount is null or _amount<=0 then raise exception 'Payment amount must be greater than zero'; end if; if not exists(select 1 from public.orders where id=_order_id and user_id=auth.uid()) then raise exception 'Order not found'; end if; if _amount > (select greatest(total_amount-coalesce((select sum(amount_paid) from public.order_installments where order_id=_order_id),0),0) from public.orders where id=_order_id) then raise exception 'Payment exceeds outstanding order balance'; end if; for r in select * from public.order_installments where order_id=_order_id and status<>'paid' order by due_date,installment_number for update loop exit when remaining<=0; applied:=least(remaining,greatest(r.amount_due-r.amount_paid,0)); update public.order_installments set amount_paid=amount_paid+applied,status=case when amount_paid+applied>=amount_due then 'paid' else 'partial' end,paid_at=case when amount_paid+applied>=amount_due then now() else paid_at end,payment_id=coalesce(_payment_id,payment_id),updated_at=now() where id=r.id; remaining:=remaining-applied; end loop; return remaining; end; $$; revoke all on function public.apply_flexible_installment_payment(uuid,numeric,uuid) from public; grant execute on function public.apply_flexible_installment_payment(uuid,numeric,uuid) to authenticated;
create or replace view public.my_properties as select o.id as order_id,o.user_id,o.total_amount,o.payment_status,o.created_at,i.property_id as item_property_id,i.plot_id,i.property_name,i.property_type,i.quantity,i.price as unit_price from public.orders o cross join lateral jsonb_to_recordset(coalesce(o.items,'[]'::jsonb)) i(property_id text,plot_id text,property_name text,property_type text,quantity integer,price numeric) where o.user_id=auth.uid() and o.payment_status in ('paid','completed','awaiting_approval');
